{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "In fed volunteers, 100 mg oral trazodone had an absolute bioavailability of 65% vs IV, directly supporting F >= 20% under fed conditions."
    },
    {
      "card_ids": ["C27"],
      "claim": "In fed patients, isoniazid oral bioavailability was 78%, supporting F >= 20% under fed conditions."
    },
    {
      "card_ids": ["C01"],
      "claim": "Procainamide absolute oral bioavailability was 75% vs IV in normal volunteers, representative of multiple quantitative transferred values all above the 20% threshold."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All transferred evidence molecules support high absolute oral bioavailability; fed-state measurements were 65% and 78%, and other quantitative absolute values ranged from 44% to 92%, all above the 20% threshold.",
  "evidence_gaps": [
    "Only two records explicitly report fed-state conditions; the remaining quantitative records are fasting or unspecified, so direct fed-state support rests on those two.",
    "Some transferred records are qualitative ('good bioavailability'/'high oral availability') and not threshold-specific, but they are not required for the prediction.",
    "Molsidomine has conflicting absolute bioavailability estimates (44% vs 65%), but both exceed the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C35", "C27", "C01"],
  "revision_action": "initial",
  "supportive_card_ids": ["C35", "C27", "C01"]
}

